output_text:
[
  {
    "id": "no_carts_in_single_file_shelf_aisles",
    "text": "Shopping carts are forbidden in single-file shelf aisles where shelves border both sides of the passage.",
    "abstraction": {
      "state_properties": {
        "singleFilePassage": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "twoSidedShelfAisle": {
          "and": [
            "singleFilePassage",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "twoSidedShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_entry_to_shelf_canyon",
    "text": "A shopper must not move a cart from an open area into a narrow shelf canyon.",
    "abstraction": {
      "state_properties": {
        "narrowShelfCanyon": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "cartEntersNarrowShelfCanyon": {
          "pre": {
            "and": [
              "hasCart",
              {
                "not": "narrowShelfCanyon"
              },
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "narrowShelfCanyon"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartEntersNarrowShelfCanyon"
    }
  },
  {
    "id": "park_at_mouth_before_narrow_aisle",
    "text": "After arriving with a cart at the mouth of a narrow shelf aisle, the shopper is obliged to park the cart before continuing the aisle visit.",
    "abstraction": {
      "state_properties": {
        "narrowAisleMouth": "at(3,3)"
      },
      "events": {
        "arriveAtNarrowAisleMouthWithCart": {
          "pre": {
            "and": [
              "hasCart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": {
            "and": [
              "narrowAisleMouth",
              "hasCart"
            ]
          }
        },
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "arriveAtNarrowAisleMouthWithCart",
      "discharge": "parkCart"
    }
  },
  {
    "id": "hands_free_collection_in_narrow_aisle",
    "text": "Items located in the narrow two-sided shelf aisle must be collected while the shopper is not holding a cart.",
    "abstraction": {
      "state_properties": {
        "narrowShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "collectFromNarrowShelfAisle": {
          "pre": {
            "and": [
              "narrowShelfAisle",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "collectFromNarrowShelfAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "park_only_in_wide_layby",
    "text": "A cart may only be parked in a wide open lay-by, not beside shelves or inside constricted passages.",
    "abstraction": {
      "state_properties": {
        "wideOpenLayby": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                8
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "parkCart",
          {
            "not": "wideOpenLayby"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "Whenever a shopper parks a cart, they are obliged to retrieve a cart before leaving the store.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "cart_required_in_checkout_run",
    "text": "The eastbound checkout corridor toward the exit must not be traversed without a cart.",
    "abstraction": {
      "state_properties": {
        "checkoutRun": {
          "or": [
            "at(3,7)",
            "at(4,7)",
            "at(5,7)",
            "at(6,7)",
            "at(7,7)",
            "at(8,7)",
            "at(9,7)",
            "at(10,7)"
          ]
        },
        "wideCheckoutRun": {
          "and": [
            "checkoutRun",
            {
              "ge": [
                "freeWidthH",
                12
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "wideCheckoutRun",
          "E",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "obtain_cart_before_shopping",
    "text": "Every shopper is obliged to take a cart before doing the rest of their shopping trip.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "takeCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "takeCart"
    }
  }
]
